package com.example.discussions.controller;import com.example.discussions.dto.Responses.*;import com.example.discussions.exception.ApiException;import com.example.discussions.model.User;import com.example.discussions.repository.*;import com.example.discussions.service.CurrentUser;import org.springframework.web.bind.annotation.*;import org.springframework.transaction.annotation.Transactional;@RestController @RequestMapping("/api/users") @Transactional(readOnly=true) public class UserController{private final UserRepository users;private final DiscussionRepository discussions;private final VoteRepository votes;private final CurrentUser current;public UserController(UserRepository u,DiscussionRepository d,VoteRepository v,CurrentUser current){users=u;discussions=d;votes=v;this.current=current;}@GetMapping("/{username}")public Profile profile(@PathVariable String username){var u=find(username);var list=discussions.findAll().stream().filter(d->d.author.id.equals(u.id)).map(d->DiscussionView.of(d,votes.countByDiscussion(d),false)).toList();return new Profile(u.id,u.username,u.displayName,u.bio,u.role.name(),u.createdAt,list);}@PutMapping("/{username}/role")@Transactional public User role(@PathVariable String username,@RequestParam User.Role role){var admin=current.admin();if(role==User.Role.ADMIN)throw ApiException.badRequest("Назначать можно только роль модератора или участника");var u=find(username);if(admin.id.equals(u.id))throw ApiException.badRequest("Нельзя изменить собственную роль");u.role=role;return users.save(u);}private User find(String username){return users.findByUsernameIgnoreCase(username).orElseThrow(()->ApiException.notFound("Пользователь не найден"));}}
